// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tier ladder: own GET, then vendor plain, render, premium
// Flo: start at the host's cached tier > T1 own GET > judge (good / gone / block) > climb: first available vendor per mode, spend guard, record spend > save via pageSave > remember the working tier
// I/O: URL (caller) + Backend (real or mock) > Outc with tier, vendor, credits; errors NeedVendor-exhausted, Blocked, OverCap, KillOn
// ===================================================================
const std = @import("std"); const urln = @import("ut-urlz-norm.zig"); const tmfx = @import("nt-fetc-time.zig"); const vali = @import("sc-reco-vali.zig"); const chrs = @import("pa-char-dete.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const base = @import("nt-vend-base.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .agez = 7 * 86400000, .skip = 3, .perm = @as([]const []const u8, &.{ "NotText", "TooBig", "BadUrl", "BlockedHost", "CharUnsupported", "RedirectLoop", "TooManyRedirects" }) };
pub const Ladd = struct { gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, back: base.Backend, go: bool = false, priv: bool = false };
const Judg = enum { good, gone, block };
fn judge(aren: std.mem.Allocator, got: pipe.Got, prev: ?inde.Row) !Judg { if (got.code == 304 and prev != null) return .good; if (got.code == 404 or got.code == 410) return .gone; if (got.code >= 200 and got.code < 300) { const utf8 = chrs.utf8Conv(aren, chrs.charFind(got.ctyp, got.body), got.body) catch return .block; return if ((vali.pageVali(aren, got.ctyp, utf8) catch .bloc) == .okay) .good else .block; } if (got.code == 401 or got.code == 403 or got.code == 429 or got.code == 503) return .block; return .gone; }
pub fn tierGet(dbzz: *sqli.Db, host: []const u8) !?struct { tier: i64, timz: i64, t1fz: i64 } { var stmt = try dbzz.prep("SELECT tier,timz,t1fz FROM tier WHERE host=?1;"); defer stmt.fini(); try stmt.bindText(1, host); if (!try stmt.step()) return null; return .{ .tier = stmt.colInt(0), .timz = stmt.colInt(1), .t1fz = stmt.colInt(2) }; }
pub fn tierSet(dbzz: *sqli.Db, host: []const u8, tier: i64, vend: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz) VALUES(?1,?2,?3,?4) ON CONFLICT(host) DO UPDATE SET tier=?2,vend=?3,timz=?4;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindInt(2, tier); try stmt.bindText(3, vend); try stmt.bindInt(4, timz); _ = try stmt.step(); }
pub fn tierOne(dbzz: *sqli.Db, host: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz,t1fz) VALUES(?1,1,'',?2,0) ON CONFLICT(host) DO UPDATE SET t1fz=0,timz=?2;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindInt(2, timz); _ = try stmt.step(); }
pub fn tierFail(dbzz: *sqli.Db, host: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz,t1fz) VALUES(?1,2,'',?2,1) ON CONFLICT(host) DO UPDATE SET t1fz=t1fz+1,timz=?2;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindInt(2, timz); _ = try stmt.step(); }
fn permOk(name: []const u8) bool { for (CF.perm) |item| if (std.mem.eql(u8, item, name)) return true; return false; }
fn logVend(self: *Ladd, urlz: []const u8, code: i64, mode: base.Mode, vend: []const u8, cred: u32, micr: u64, note: []const u8, now: i64) !void { try inde.logzAdd(self.dbzz, .{ .urlz = urlz, .code = code, .tier = @backingInt(mode), .vend = vend, .cred = cred, .micr = @intCast(micr), .robo = "none", .timz = now, .note = note }); }
pub fn laddFetc(self: *Ladd, aren: std.mem.Allocator, urlz: []const u8) !pipe.Outc { const norm = try urln.urlNorm(aren, urlz); const part = try urln.urlSplit(norm); const prev = try inde.pageGet(self.dbzz, aren, norm); const now0 = pipe.nowMs(self.iozz); var start: i64 = 2; var skip1 = false; if (try tierGet(self.dbzz, part.host)) |hit| { start = @max(hit.tier, 2); if (start > 2 and now0 - hit.timz > CF.agez) start -= 1; skip1 = hit.t1fz >= CF.skip; }
if (!skip1) { const cond: @import("nt-fetc-owns.zig").Cond = if (prev) |row| .{ .etag = row.etag, .lmod = row.lmod } else .{}; if (tmfx.fetcTime(self.gpaz, self.iozz, urlz, try pipe.optsMake(aren, self.conf, self.priv), cond)) |resp| { var rsp = resp; defer rsp.free(self.gpaz); const got: pipe.Got = .{ .code = rsp.code, .ctyp = rsp.ctyp, .body = rsp.body, .etag = rsp.etag, .lmod = rsp.lmod, .retr = rsp.retr }; const jud = try judge(aren, got, prev); if (jud != .block) { try tierOne(self.dbzz, part.host, now0); return pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got); } try logVend(self, norm, rsp.code, .plain, "", 0, 0, "own GET blocked, climbing", now0); try tierFail(self.dbzz, part.host, now0); } else |err| { if (permOk(@errorName(err)) or !std.mem.eql(u8, @errorName(err), "NeedVendor")) return err; try logVend(self, norm, 0, .plain, "", 0, 0, "own GET needs vendor", now0); try tierFail(self.dbzz, part.host, now0); } }
var down = @as([3]bool, @splat(false)); var tried: u8 = 0; const modes = [_]base.Mode{ .plain, .rend, .prem };
for (modes) |mode| { if (@backingInt(mode) < start) continue; var pick: ?base.Vend = null; var cost: u32 = 0; var deci: spen.Deci = .{ .okay = false };
for (self.conf.vend_orde) |name| { const vend = base.vendFind(name) orelse continue; if (down[@backingInt(vend)]) continue; cost = base.credCost(vend, mode); const dec = try spen.spenChek(self.dbzz, self.conf, vend, cost, pipe.nowMs(self.iozz), self.go); if (!dec.okay) { if (std.mem.eql(u8, dec.why, "kill switch on")) return error.KillOn; down[@backingInt(vend)] = true; continue; } pick = vend; deci = dec; break; }
const vend = pick orelse { if (tried == 0) return error.OverCap; return error.Blocked; }; tried += 1; const now = pipe.nowMs(self.iozz); const rsp = self.back.call(self.back.ctx, aren, self.iozz, vend, .{ .urlz = urlz, .mode = mode }) catch |err| { try logVend(self, norm, 0, mode, base.vendName(vend), 0, 0, @errorName(err), now); down[@backingInt(vend)] = true; continue; };
if (rsp.errz.len > 0) { try logVend(self, norm, rsp.code, mode, base.vendName(vend), 0, 0, rsp.errz, now); down[@backingInt(vend)] = true; continue; }
const micr: u64 = if (deci.paid) deci.micr else 0; if (rsp.cred > 0) try spen.spenRec(self.dbzz, vend, rsp.cred, micr, now); const got: pipe.Got = .{ .code = rsp.code, .ctyp = rsp.ctyp, .body = rsp.body, .tier = @backingInt(mode), .vend = base.vendName(vend), .cred = @intCast(rsp.cred), .micr = @intCast(micr) }; const jud = try judge(aren, got, prev);
if (jud == .block) { try logVend(self, norm, rsp.code, mode, base.vendName(vend), rsp.cred, micr, "vendor result blocked, climbing", now); continue; }
var outc = try pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got); outc.tier = @backingInt(mode); outc.vend = base.vendName(vend); outc.cred = rsp.cred; outc.micr = micr; try tierSet(self.dbzz, part.host, @backingInt(mode), base.vendName(vend), now); return outc; }
if (tried == 0) return error.OverCap; return error.Blocked; }
